<?php declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';if(vendor_user())redirect('/vendor/dashboard.php');if(is_post()){verify_csrf();if(!rate_limit('vendor-login',5,900)||!attempt_vendor_login(trim((string)input('identity')),(string)input('password')))flash('error','Invalid credentials or too many attempts.');else redirect('/vendor/dashboard.php');}$notices=take_flashes();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vendor sign in · Hunter</title><link rel="stylesheet" href="<?=e(app_url('/assets/css/style.css'))?>"></head><body class="login-page"><main class="login-card"><h1>Vendor portal</h1><p>Redeem Hunter gift codes securely.</p><?php foreach($notices as $n):?><div class="alert <?=e($n['type'])?>"><?=e($n['message'])?></div><?php endforeach?><form method="post"><?=csrf_field()?><div class="field"><label>Username or email</label><input name="identity" autocomplete="username" required autofocus></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required></div><button class="btn">Sign in</button></form></main></body></html>
